import { z } from "zod";
import { objectIdSchema, paginationSchema } from "../../lib/pagination.js";
import { PAYMENT_METHODS } from "../payments/gateway.js";
import { ORDER_STATUSES, PAYMENT_STATUSES } from "./order.model.js";

export const checkoutSchema = z
  .object({
    addressId: objectIdSchema,
    paymentMethod: z.enum(PAYMENT_METHODS),
    // Generated by the browser once per checkout attempt: a double click or a retried request returns the same order.
    idempotencyKey: z.string().uuid("Invalid idempotency key"),
  })
  .strict();

export type CheckoutInput = z.infer<typeof checkoutSchema>;

export const razorpayVerifySchema = z
  .object({
    razorpay_order_id: z.string().regex(/^order_[A-Za-z0-9]{6,40}$/),
    razorpay_payment_id: z.string().regex(/^pay_[A-Za-z0-9]{6,40}$/),
    razorpay_signature: z.string().regex(/^[a-f0-9]{64}$/),
  })
  .strict();

export const cancelOrderSchema = z.object({ reason: z.string().trim().max(300).default("") }).strict();

export const customerOrdersQuerySchema = paginationSchema.strict();

const dateParam = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "Use YYYY-MM-DD").transform((value) => new Date(`${value}T00:00:00+05:30`));

export const adminOrdersQuerySchema = z
  .object({
    q: z.string().trim().max(100).optional(),
    status: z.enum(ORDER_STATUSES).optional(),
    paymentStatus: z.enum(PAYMENT_STATUSES).optional(),
    paymentMethod: z.enum(PAYMENT_METHODS).optional(),
    from: dateParam.optional(),
    to: dateParam.optional(),
  })
  .extend(paginationSchema.shape)
  .strict();

export type AdminOrdersQuery = z.infer<typeof adminOrdersQuerySchema>;

export const updateStatusSchema = z
  .object({
    status: z.enum(ORDER_STATUSES),
    note: z.string().trim().max(300).default(""),
    tracking: z.object({ carrier: z.string().trim().min(1).max(60), number: z.string().trim().min(1).max(60), url: z.string().trim().url().max(300).refine((url) => url.startsWith("https://"), "Use an https link").or(z.literal("")).default("") }).strict().optional(),
  })
  .strict()
  .refine((input) => input.status !== "shipped" || input.tracking, { path: ["tracking"], message: "Tracking details are required to mark an order shipped" });

export type UpdateStatusInput = z.infer<typeof updateStatusSchema>;

export const refundSchema = z
  .object({
    // Omitted means "everything not yet refunded".
    amount: z.number().int().min(100, "Refunds start at ₹1").optional(),
    reason: z.string().trim().min(1).max(300),
  })
  .strict();

export type RefundInput = z.infer<typeof refundSchema>;
